-- Racing surface and circuit type for the Tracks tab. Safe to re-run.
alter table public.track_venues add column if not exists surface text;
alter table public.track_venues add column if not exists surface_note text;
alter table public.track_venues add column if not exists circuit_type text check (circuit_type is null or circuit_type in ('purpose-built', 'public-road', 'airfield', 'oval'));
alter table public.track_venues add column if not exists type_note text;
notify pgrst, 'reload schema';

update public.track_venues set surface = 'Asphalt (tarmac)', surface_note = null, circuit_type = 'purpose-built', type_note = 'Described by Wikipedia as the first purpose-built post-war racing circuit in England.' where name = 'Brands Hatch';
update public.track_venues set surface = 'Asphalt', surface_note = 'Resurfaced with asphalt in two layers in January 2018, per the contractor.', circuit_type = 'purpose-built', type_note = 'A race track at Montmeló, built in 1991.' where name = 'Circuit de Barcelona-Catalunya';
update public.track_venues set surface = 'Asphalt', surface_note = 'Drainage grooves are cut into the asphalt on the start-finish straight.', circuit_type = 'purpose-built', type_note = 'A 14 km public-road circuit until 1979, now a permanent racing facility removed from the public road network in 2000.' where name = 'Circuit de Spa-Francorchamps';
update public.track_venues set surface = 'Asphalt', surface_note = 'Both the tri-oval and the road course are asphalt; the track was repaved in 1978 and 2010.', circuit_type = 'oval', type_note = 'The main layout is a 2.5 mile tri-oval; the road course uses part of the oval plus a flat infield.' where name = 'Daytona Intl Speedway';
update public.track_venues set surface = 'Asphalt', surface_note = null, circuit_type = 'purpose-built', type_note = 'A permanent circuit built in 1932, with a drag strip and rallycross track alongside.' where name = 'Hockenheimring';
update public.track_venues set surface = 'Asphalt', surface_note = null, circuit_type = 'oval', type_note = 'A 1.5 mile oval, with a 2.3 mile roval that adds an infield road course.' where name = 'Homestead-Miami Speedway';
update public.track_venues set surface = 'Asphalt, with a strip of brick', surface_note = 'Only the brick strip at the start-finish line remains from the original brick surface.', circuit_type = 'oval', type_note = 'A 2.5 mile rectangular oval, with a road course that uses part of the oval.' where name = 'Indianapolis Motor Speedway';
update public.track_venues set surface = 'Asphalt', surface_note = null, circuit_type = 'purpose-built', type_note = 'A permanent circuit designed and cleared in the mid-1950s; it opened in 1961.' where name = 'Kyalami Grand Prix Circuit';
update public.track_venues set surface = 'Asphalt (tarmac)', surface_note = null, circuit_type = 'public-road', type_note = 'Private race-specific sections joined by public roads used only for the 24 Hours; a large portion is still the D338.' where name = 'Le Mans - Circuit International de la Sarthe';
update public.track_venues set surface = 'Asphalt', surface_note = null, circuit_type = 'purpose-built', type_note = 'A road course built over hilly natural terrain in the Litchfield Hills.' where name = 'Lime Rock Park';
update public.track_venues set surface = 'Asphalt', surface_note = null, circuit_type = 'purpose-built', type_note = 'Built on land bought to create a world-class road racing facility.' where name = 'Michelin Raceway Road Atlanta';
update public.track_venues set surface = null, surface_note = 'Concrete was laid at the turn apexes in 1990 and removed in 2006; no source I read names the racing surface.', circuit_type = 'purpose-built', type_note = 'A permanent road course opened in 1962 for sports car racing.' where name = 'Mid-Ohio Sports Car Course';
update public.track_venues set surface = null, surface_note = 'No source I could read states the racing surface.', circuit_type = 'public-road', type_note = 'A street circuit used as a public road whenever no racing event is on.' where name = 'Mount Panorama Circuit';
update public.track_venues set surface = 'Asphalt', surface_note = null, circuit_type = 'purpose-built', type_note = 'The present closed circuit was built in 1973; earlier races ran on public roads from the 1920s.' where name = 'Mugello Circuit';
update public.track_venues set surface = 'Asphalt and concrete', surface_note = 'The Nordschleife is asphalt and concrete (concrete at the banked Karussell); the Grand Prix circuit is asphalt.', circuit_type = 'purpose-built', type_note = 'Built for racing, but the Nordschleife is technically operated as a public toll road when open for touring.' where name = 'Nürburgring';
update public.track_venues set surface = 'Asphalt', surface_note = null, circuit_type = 'purpose-built', type_note = 'A permanent road course.' where name = 'Road America';
update public.track_venues set surface = 'Asphalt and concrete', surface_note = 'About 3.04 miles of asphalt and 0.7 miles of concrete, some of it original wartime runway slabs.', circuit_type = 'airfield', type_note = 'Built on part of Hendricks Army Airfield, now Sebring Regional Airport.' where name = 'Sebring International Raceway';
update public.track_venues set surface = 'Asphalt', surface_note = 'Resurfaced with an asphalt solution, per the contractor.', circuit_type = 'airfield', type_note = 'Built on a former RAF bomber station; the three wartime runways lie within the present track outline.' where name = 'Silverstone Racing Circuit';
update public.track_venues set surface = 'Paved (special asphalt on the South Course)', surface_note = 'The official course guide lists the main course as paved and the South Course as special asphalt.', circuit_type = 'purpose-built', type_note = 'A permanent circuit built from 1962 as a Honda test track.' where name = 'Suzuka Circuit';
update public.track_venues set surface = 'Asphalt', surface_note = null, circuit_type = 'purpose-built', type_note = 'A permanent road course.' where name = 'Virginia International Raceway';
update public.track_venues set surface = 'Asphalt and concrete', surface_note = 'The Grand Prix circuit with the Inner Loop chicane is asphalt and concrete; the short circuit is asphalt.', circuit_type = 'purpose-built', type_note = 'Opened as a permanent circuit in 1956, replacing earlier races on village streets.' where name = 'Watkins Glen International Speedway';
update public.track_venues set surface = 'Paved', surface_note = 'Described only as a paved road racing track.', circuit_type = 'purpose-built', type_note = 'A permanent road racing circuit.' where name = 'WeatherTech Raceway Laguna Seca';
update public.track_venues set surface = 'Paved (graywacke aggregate)', surface_note = 'The surface uses graywacke aggregate shipped from a quarry in Shropshire, England.', circuit_type = 'purpose-built', type_note = 'A permanent circuit on Yas Island.' where name = 'Yas Marina Circuit';
update public.track_venues set surface = null, surface_note = null, circuit_type = 'oval', type_note = 'Described by Traxion as a fictional oval.' where name = 'Eaglerock Speedway';
