update public.track_venues set surface = null, surface_note = null, circuit_type = 'purpose-built', type_note = 'A fictional race track in the New England woods.' where name = 'Maple Valley';
update public.track_venues set surface = null, surface_note = null, circuit_type = 'oval', type_note = 'Described as reminiscent of a roval: an oval with road course configurations.' where name = 'Sunset Peninsula Raceway';
